class EgateCmdGenerator(object):
    """
    content all _generate function of lteemulator.
    """

    @staticmethod
    def __generate_cmd(template, arglist, kwargs):
        cmd = template.strip()
        for argname in arglist:
            argvalue = kwargs[argname]
            if argvalue is not None:
                cmd = cmd + " {}={}".format(argname, argvalue)
        return cmd

